/**
 * Generic page for reports computed on the server ({ title, columns, rows, totals, note }): report menu,
 * period and dimension filters, sortable table with search, totals row, and Excel / PDF / CSV export
 * through the shared exporter (RALGA header, period, generated by / at; exports are audited).
 */
import * as React from "react";
import { Link, useSearchParams } from "react-router-dom";
import { useQuery } from "react-query";
import { ArrowDown, ArrowUp, FileText, Search } from "lucide-react";
import pocketbase from "@/lib/pocketbase";
import { exportReport, CellFormat } from "@/lib/exporter";
import { showDay } from "@/lib/ims";
import ExportMenu from "@/components/enterprise/ExportMenu";
import { EmptyState, ListSkeleton, PageHeader } from "@/components/enterprise/ui";
import { cn } from "@/utils";

export interface ServerReportResult {
  title: string;
  columns: { key: string; label: string; type: string }[];
  rows: Record<string, any>[];
  totals: Record<string, number>;
  note: string;
  generated_at: string;
}

type FilterKey = "from" | "to" | "supplier" | "department";

const FORMAT: Record<string, CellFormat> = { money: "money", number: "number", pct: "percent", date: "date" };
const cellText = (type: string, v: any) => {
  if (v === null || v === undefined || v === "") return "—";
  if (type === "money") return Math.round(Number(v)).toLocaleString("en-US");
  if (type === "number") return Number(v).toLocaleString("en-US");
  if (type === "pct") return `${Number(v).toLocaleString("en-US")}%`;
  if (type === "date") return showDay(String(v));
  if (type === "status") return String(v).replace(/_/g, " ");
  return String(v);
};
const selectCls = "h-9 w-full rounded-md border border-slate-200 bg-white px-2.5 text-[13px] text-slate-800 focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20";

export default function ServerReportPage({
  title, description, breadcrumbs, groups, run, filters, exportPermission, defaultFrom,
}: {
  title: string;
  description: string;
  breadcrumbs: { title: string; link: string }[];
  groups: { title: string; items: [string, string][] }[];
  run: (key: string, f: Record<string, string>) => Promise<ServerReportResult>;
  filters: FilterKey[];
  exportPermission?: string[];
  /** Start of the default period, e.g. the fiscal year start. */
  defaultFrom?: string;
}) {
  const [params, setParams] = useSearchParams();
  const first = groups[0]?.items[0]?.[0] || "";
  const key = params.get("r") || first;
  const [f, setF] = React.useState<Record<string, string>>({ from: defaultFrom || `${new Date().getFullYear()}-01-01`, to: new Date().toISOString().slice(0, 10), supplier: "", department: "" });
  const [search, setSearch] = React.useState("");
  const [sort, setSort] = React.useState<{ key: string; dir: 1 | -1 } | null>(null);
  const ref = useQuery(["server-report-filters", filters.join()], async () => ({
    suppliers: filters.includes("supplier") ? await pocketbase.collection("suppliers").getFullList({ sort: "name", fields: "id,name" }) : [],
    departments: filters.includes("department") ? await pocketbase.collection("departments").getFullList({ sort: "name", fields: "id,name" }) : [],
  }));
  const active = Object.fromEntries(Object.entries(f).filter(([k]) => filters.includes(k as FilterKey)));
  const q = useQuery(["server-report", title, key, active], () => run(key, active), { keepPreviousData: true, enabled: Boolean(key) });
  const r = q.data;
  const label = groups.flatMap((g) => g.items).find(([k]) => k === key)?.[1] || r?.title || "Report";
  const rows = React.useMemo(() => {
    const s = search.trim().toLowerCase();
    let out = (r?.rows || []).filter((row) => !s || Object.values(row).some((v) => String(v ?? "").toLowerCase().includes(s)));
    if (sort) out = [...out].sort((a, b) => (a[sort.key] > b[sort.key] ? 1 : a[sort.key] < b[sort.key] ? -1 : 0) * sort.dir);
    return out;
  }, [r, search, sort]);
  const nameOf = (list: any[] | undefined, id: string) => list?.find((x) => x.id === id)?.name;
  const subtitle = [
    filters.includes("from") && f.from && `from ${showDay(f.from)}`,
    filters.includes("to") && f.to && `to ${showDay(f.to)}`,
    f.supplier && filters.includes("supplier") && nameOf(ref.data?.suppliers, f.supplier),
    f.department && filters.includes("department") && nameOf(ref.data?.departments, f.department),
  ].filter(Boolean).join(" · ");

  const doExport = (format: "xlsx" | "pdf" | "csv") =>
    exportReport({
      title: label, subtitle, rows, format, what: `report:${key}`, orientation: (r?.columns.length || 0) > 6 ? "landscape" : "portrait",
      totals: (r?.columns || []).filter((c) => r?.totals[c.key] !== undefined && ["money", "number"].includes(c.type)).map((c) => c.label),
      columns: (r?.columns || []).map((c) => ({ header: c.label, value: (row: any) => row[c.key], format: FORMAT[c.type] || "text", width: c.type === "text" || c.type === "status" ? 24 : 14 })),
    });

  return (
    <div className="space-y-4 px-3 sm:px-4">
      <PageHeader title={title} description={description} breadcrumbs={breadcrumbs} />
      <div className="grid gap-4 lg:grid-cols-[230px_minmax(0,1fr)]">
        <nav aria-label="Reports" className="space-y-4">
          <label className="block text-[12.5px] font-medium text-slate-700 lg:hidden">
            Report
            <select className={cn(selectCls, "mt-1")} value={key} onChange={(e) => setParams({ r: e.target.value })}>
              {groups.map((g) => <optgroup key={g.title} label={g.title}>{g.items.map(([k, l]) => <option key={k} value={k}>{l}</option>)}</optgroup>)}
            </select>
          </label>
          <div className="hidden space-y-4 lg:block">
            {groups.map((g) => (
              <div key={g.title}>
                <p className="mb-1.5 px-2 text-[11px] font-semibold uppercase tracking-widest text-slate-400">{g.title}</p>
                {g.items.map(([k, l]) => (
                  <button key={k} type="button" onClick={() => { setParams({ r: k }); setSort(null); }}
                    className={cn("flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left text-[13px]", k === key ? "bg-ralga-navy/[0.07] font-semibold text-ralga-navy" : "text-slate-600 hover:bg-slate-100")}>
                    <FileText size={14} className="shrink-0 text-slate-400" /> {l}
                  </button>
                ))}
              </div>
            ))}
          </div>
        </nav>

        <div className="min-w-0 space-y-3">
          <div className="grid grid-cols-2 gap-2 rounded-lg border border-slate-200 bg-white p-3 shadow-card sm:grid-cols-3 xl:grid-cols-5">
            {filters.includes("from") && <label className="text-[12px] font-medium text-slate-600">From<input type="date" className={cn(selectCls, "mt-1")} value={f.from} onChange={(e) => setF({ ...f, from: e.target.value })} /></label>}
            {filters.includes("to") && <label className="text-[12px] font-medium text-slate-600">To / as of<input type="date" className={cn(selectCls, "mt-1")} value={f.to} onChange={(e) => setF({ ...f, to: e.target.value })} /></label>}
            {filters.includes("supplier") && (
              <label className="text-[12px] font-medium text-slate-600">Supplier
                <select className={cn(selectCls, "mt-1")} value={f.supplier} onChange={(e) => setF({ ...f, supplier: e.target.value })}><option value="">All</option>{(ref.data?.suppliers || []).map((s: any) => <option key={s.id} value={s.id}>{s.name}</option>)}</select>
              </label>
            )}
            {filters.includes("department") && (
              <label className="text-[12px] font-medium text-slate-600">Department
                <select className={cn(selectCls, "mt-1")} value={f.department} onChange={(e) => setF({ ...f, department: e.target.value })}><option value="">All</option>{(ref.data?.departments || []).map((d: any) => <option key={d.id} value={d.id}>{d.name}</option>)}</select>
              </label>
            )}
            <label className="col-span-2 text-[12px] font-medium text-slate-600 sm:col-span-1">Search in results
              <span className="relative mt-1 block">
                <Search size={14} className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400" />
                <input className={cn(selectCls, "pl-8")} value={search} onChange={(e) => setSearch(e.target.value)} />
              </span>
            </label>
          </div>

          <section className="overflow-hidden rounded-lg border border-slate-200 bg-white shadow-card">
            <div className="flex flex-wrap items-center justify-between gap-2 border-b border-slate-100 px-4 py-3">
              <div>
                <h2 className="text-[15px] font-semibold text-slate-900">{label}</h2>
                <p className="text-[12px] text-slate-500">{subtitle || "All records"} · {rows.length} row{rows.length === 1 ? "" : "s"}{r ? ` · generated ${new Date(r.generated_at).toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short" })}` : ""}</p>
              </div>
              <ExportMenu onExport={doExport} permission={exportPermission} disabled={!rows.length} />
            </div>
            {q.isLoading ? <div className="p-4"><ListSkeleton rows={6} /></div> : q.isError ? (
              <EmptyState icon={FileText} title="Report not available" text={(q.error as any)?.message || "You may not have access to this report."} />
            ) : !rows.length ? (
              <EmptyState icon={FileText} title="Nothing to report" text="No records match these filters." />
            ) : (
              <div className="overflow-x-auto">
                <table className="dnr-grid w-full">
                  <thead>
                    <tr>
                      {r!.columns.map((c) => {
                        const num = ["money", "number", "pct"].includes(c.type);
                        const sorted = sort?.key === c.key;
                        return (
                          <th key={c.key} className={cn(num && "text-right")}>
                            <button type="button" className="inline-flex items-center gap-1 uppercase" onClick={() => setSort(sorted ? { key: c.key, dir: sort!.dir === 1 ? -1 : 1 } : { key: c.key, dir: num ? -1 : 1 })}>
                              {c.label}{sorted && (sort!.dir === 1 ? <ArrowUp size={11} /> : <ArrowDown size={11} />)}
                            </button>
                          </th>
                        );
                      })}
                    </tr>
                  </thead>
                  <tbody>
                    {rows.map((row, i) => (
                      <tr key={i}>
                        {r!.columns.map((c, ci) => {
                          const num = ["money", "number", "pct"].includes(c.type);
                          const text = cellText(c.type, row[c.key]);
                          return (
                            <td key={c.key} className={cn(num && "whitespace-nowrap text-right tabular-nums", c.type === "date" && "whitespace-nowrap")}>
                              {ci === 0 && row.link ? <Link to={row.link} className="font-medium text-primaryDark hover:underline">{text}</Link> : c.type === "status" ? <span className="capitalize">{text}</span> : text}
                            </td>
                          );
                        })}
                      </tr>
                    ))}
                  </tbody>
                  {Object.keys(r!.totals || {}).length > 0 && (
                    <tfoot>
                      <tr className="border-t-2 border-slate-200 font-semibold">
                        {r!.columns.map((c, ci) => (
                          <td key={c.key} className={cn(["money", "number", "pct"].includes(c.type) && "whitespace-nowrap text-right tabular-nums")}>{ci === 0 ? "Total" : r!.totals[c.key] !== undefined ? cellText(c.type, r!.totals[c.key]) : ""}</td>
                        ))}
                      </tr>
                    </tfoot>
                  )}
                </table>
              </div>
            )}
            {r?.note && <p className="border-t border-slate-100 px-4 py-2.5 text-[12px] text-slate-500">{r.note}</p>}
          </section>
        </div>
      </div>
    </div>
  );
}
